<script>
(()=>{
  const page=document.querySelector('.podcast-index-page'); if(!page)return;
  const cards=[...page.querySelectorAll('[data-podcast-card]')], filters=[...page.querySelectorAll('[data-podcast-filter]')], empty=page.querySelector('[data-podcast-empty]'), loadMore=page.querySelector('[data-podcast-load-more]'), result=page.querySelector('[data-podcast-result-count]');
  let active='all', limit=6;
  const render=()=>{const matches=cards.filter(card=>active==='all'||card.dataset.categoryId===active);let shown=0;cards.forEach(card=>{const visible=matches.includes(card)&&shown<limit;card.hidden=!visible;if(visible)shown++});if(empty)empty.hidden=matches.length>0;if(loadMore)loadMore.hidden=shown>=matches.length;if(result)result.textContent=matches.length?copy.result.replace('%s',shown).replace('%s',matches.length):''};
  const choose=value=>{active=value;limit=6;filters.forEach(filter=>{const on=filter.dataset.podcastFilter===value;filter.classList.toggle('is-active',on);filter.setAttribute('aria-pressed',on?'true':'false')});render()};
  filters.forEach(filter=>filter.addEventListener('click',()=>choose(filter.dataset.podcastFilter)));
  page.querySelectorAll('[data-podcast-filter-link]').forEach(link=>link.addEventListener('click',()=>{choose(link.dataset.podcastFilterLink);document.querySelector('#latest')?.scrollIntoView({behavior:'smooth',block:'start'})}));
  loadMore?.addEventListener('click',()=>{limit+=6;render()}); render();

  const player=document.querySelector('[data-podcast-global-player]'),audio=player?.querySelector('[data-podcast-global-audio]'); if(!player||!audio)return;
  const title=player.querySelector('[data-podcast-player-title]'),art=player.querySelector('[data-podcast-player-art]'),status=player.querySelector('[data-podcast-player-status]'),toggle=player.querySelector('[data-podcast-player-toggle]'),seek=player.querySelector('[data-podcast-player-seek]'),current=player.querySelector('[data-podcast-player-current]'),duration=player.querySelector('[data-podcast-player-duration]');
  const fmt=value=>{const seconds=Math.max(0,Math.floor(Number(value)||0));return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')};
  const copy=<?=json_encode($P,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;
  const open=button=>{const url=button.dataset.audioUrl;if(!url){if(button.dataset.episodeUrl)location.href=button.dataset.episodeUrl;return}if(audio.src!==url){audio.src=url;audio.load();title.textContent=button.dataset.title||'Saradeeeb podcast';art.src=button.dataset.cover||'';art.alt=button.dataset.title||'';status.textContent='';seek.value=0;current.textContent='00:00'}player.hidden=false;audio.play().catch(()=>{status.textContent=copy.start})};
  page.querySelectorAll('[data-podcast-play]').forEach(button=>button.addEventListener('click',()=>open(button)));
  toggle.addEventListener('click',()=>{if(audio.src)audio.paused?audio.play().catch(()=>{}):audio.pause()});
  seek.addEventListener('input',()=>{if(audio.duration)audio.currentTime=(Number(seek.value)/100)*audio.duration});
  audio.addEventListener('play',()=>{toggle.textContent='❚❚';toggle.setAttribute('aria-label',copy.pause||'Pause');status.textContent=''});audio.addEventListener('pause',()=>{toggle.textContent='▶';toggle.setAttribute('aria-label',copy.play)});audio.addEventListener('loadedmetadata',()=>{duration.textContent=fmt(audio.duration)});audio.addEventListener('timeupdate',()=>{current.textContent=fmt(audio.currentTime);if(audio.duration)seek.value=(audio.currentTime/audio.duration)*100});audio.addEventListener('error',()=>{status.textContent=copy.error});player.querySelector('[data-podcast-player-close]').addEventListener('click',()=>{audio.pause();audio.removeAttribute('src');audio.load();player.hidden=true});
})();
</script>
